import fs from 'node:fs';import{pathToFileURL}from'node:url';const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('arrangement_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const preview={start:16,end:32,startName:'Verse',endName:'End Verse'},rows=[];
for(const tool of['liveArrangementPreview','liveArrangementPreviewAsync','liveArrangementApply','liveArrangementApplyAsync']){const valid=tool.includes('Preview')?preview:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const missing={...valid};delete missing[key];cases.push(missing);for(const value of[null,[],{},false,0,-1,16,32,100000,100001,'','x','Verse','End Verse'])cases.push({...valid,[key]:value});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const workflows=[];const scenarios=['normal','expire','epoch','revision','undo-missing','undo-changed','undo-epoch'];for(const phase of ['apply','undo'])for(const step of[1,2])for(const kind of['before','after','nothing','refusal','no-effect','read'])scenarios.push(`${phase}/${step}/${kind}`);for(const step of[1,2])for(const kind of['wrong-name','bad-fingerprint','bad-identity','missing-ref','null-result','changed-owned','compensate-before','compensate-after'])scenarios.push(`apply/${step}/${kind}`);
for(const async of[false,true])for(const scenario of scenarios){const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',faultStep=0,count=0,fired=false,readFail=false,compensateFail=false;
function reset(value){fault=value;count=0;fired=false;readFail=false;compensateFail=false;}
function snapshot(c,r){if(readFail){readFail=false;throw new Error('injected authoritative read failure');}return c!==undefined||r!==undefined?sim.snapshotAsync(c,r):sim.snapshot();}
function invoke(i,c){calls.push(clean({invocation:i,context:c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}));count++;const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(c&&cache.has(key))return cache.get(key);if(compensateFail&&i.operation==='locator.delete'){compensateFail=false;if(fault==='compensate-before')throw new Error('injected compensation failure');const result=sim.invoke(i);if(c)cache.set(key,result);throw new Error('injected compensation failure');}const trigger=!fired&&count===faultStep;if(trigger)fired=true;if(trigger&&['before','nothing','refusal'].includes(fault)){if(fault==='refusal')throw new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed');throw new Error(fault==='nothing'?'Nothing changed in Live: rejected locator':'injected operation failure');}let result=trigger&&fault==='no-effect'?{ok:true}:sim.invoke(i);if(c&&!(trigger&&fault==='no-effect'))cache.set(key,structuredClone(result));if(trigger){if(fault==='after')throw new Error('injected operation failure');if(fault==='read')readFail=true;if(['wrong-name','compensate-before','compensate-after'].includes(fault)){result={...result,name:'Wrong'};if(fault.startsWith('compensate-'))compensateFail=true;}if(fault==='bad-fingerprint')result={...result,createdFingerprint:'bad'};if(fault==='bad-identity')result={...result,objectIdentity:'changed'};if(fault==='missing-ref'){result={...result};delete result.ref;}if(fault==='null-result')result=null;if(fault==='changed-owned'){sim.state.arrangement.locators.find(r=>r.ref===result.ref).name='Changed';}}return result;}
const adapter={status:()=>sim.status(),snapshot:()=>snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:(c,r)=>snapshot(c,r),discoverAsync:(r,c)=>sim.discoverAsync(r,c),getAsync:(r,c)=>sim.getAsync(r,c),invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async()=>sim.status()};const host=new McpHost(adapter),results=[],states=[];const suffix=async?'Async':'';const made=await host['liveArrangementPreview'+suffix](1,preview);results.push(clean(made));const txid=JSON.parse(made.result.content[0].text).transactionId,record=host.arrangementTransactions.get(txid);async function perform(kind,key){const args={transactionId:txid,confirmation:kind,idempotencyKey:key};let result;try{result=await host[kind==='apply'?'liveArrangementApply'+suffix:async?'liveUndoAsync':'liveUndo'](results.length+1,args);}catch(e){result={error:e.message};}results.push(clean(result));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='revision')sim.invoke({operation:'locator.add',args:{name:'External',position:60,expectedCollectionRevision:sim.state.arrangement.locatorRevision}});if(scenario.startsWith('apply/')){const p=scenario.split('/');faultStep=+p[1];reset(p[2]);}for(const key of['apply-key','wrong-key','apply-key'])await perform('apply',key);reset('');if(scenario==='undo-epoch')sim.reconnect();if(scenario==='undo-missing'){sim.state.arrangement.locators.pop();}if(scenario==='undo-changed'){sim.state.arrangement.locators.at(-1).name='Other';}if(scenario.startsWith('undo/')){const p=scenario.split('/');faultStep=+p[1];reset(p[2]);}for(const key of['undo-key','wrong-undo-key','undo-key'])await perform('undo',key);reset('');await perform('undo','new-undo-key');workflows.push({async,scenario,results,states,calls,arrangement:sim.state.arrangement});}
fs.writeFileSync(new URL('host-arrangement-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
